        writeFileSync('/tmp/pyz/hit_' + i + '.bin', out);
        console.log('HIT at', i, 'len', out.length);
        if (++hits.length > 8) break;
      }
    } catch (e) {}
  }
  i++;
  if (i - start > 20000000) break;
}
console.log('done', hits.length);
EOF
