args.content:
// argparse-compatible argument parsing for test6.
// Replicates: argparse.ArgumentParser(description='Multiple markdown conversions')
// with two required string options --a and --b.

function basename(p) {
  const idx = p.lastIndexOf('/');
  return idx === -1 ? p : p.slice(idx + 1);
}

// Options in definition order (-h/--help is added first by argparse).
const OPTIONS = [
  { strings: ['-h', '--help'], dest: 'help', takesArg: false },
  { strings: ['--a'], dest: 'a', takesArg: true },
  { strings: ['--b'], dest: 'b', takesArg: true },
];

const OPTION_MAP = new Map();
for (const opt of OPTIONS) {
  for (const s of opt.strings) OPTION_MAP.set(s, opt);
}

function prog() {
  return basename(process.argv[1] || '');
}

function usageLine() {
  return 'usage: ' + prog() + ' [-h] --a A --b B';
}

function printHelpAndExit() {
  process.stdout.write(
    usageLine() + '\n' +
    '\n' +
    'Multiple markdown conversions\n' +
    '\n' +
    'options:\n' +
    '  -h, --help  show this help message and exit\n' +
    '  --a A\n' +
    '  --b B\n'
  );
  process.exit(0);
}

function errorAndExit(message) {
  process.stderr.write(usageLine() + '\n' + prog() + ': error: ' + message + '\n');
  process.exit(2);
}

// Matches argparse's _negative_number_matcher: ^-\d+$ | ^-\d*\.\d+$
function looksLikeNegativeNumber(s) {
  if (s.length < 2 || s[0] !== '-') return false;
  const rest = s.slice(1);
  if (isAllDigits(rest)) return true;
  const dot = rest.indexOf('.');
  if (dot === -1 || rest.indexOf('.', dot + 1) !== -1) return false;
  const before = rest.slice(0, dot);
  const after = rest.slice(dot + 1);
  return isAllDigits(before) && after.length > 0 && isAllDigits(after);
}

function isAllDigits(s) {
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    if (c < 48 || c > 57) return false;
  }
  return true;
}

// Mirror of argparse._get_option_tuples: prefix-match arg against known options.
// Returns a list of { opt, optionString, explicitArg, viaSep }.
function getOptionTuples(arg) {
  const result = [];
  if (arg.length >= 2 && arg[0] === '-' && arg[1] === '-') {
    // long option: --foo or --foo=bar
    const eq = arg.indexOf('=');
    const prefix = eq === -1 ? arg : arg.slice(0, eq);
    const explicitArg = eq === -1 ? null : arg.slice(eq + 1);
    for (const opt of OPTIONS) {
      for (const s of opt.strings) {
        if (s.startsWith(prefix)) {
          result.push({ opt, optionString: s, explicitArg, viaSep: eq !== -1 });
        }
      }
    }
  } else if (arg[0] === '-' && (arg.length < 2 || arg[1] !== '-')) {
    // short option: -x, -xvalue or -x=value
    const eq = arg.indexOf('=');
    const prefix = eq === -1 ? arg : arg.slice(0, eq);
    const shortPrefix = arg.slice(0, 2);
    const shortExplicit = arg.slice(2);
    for (const opt of OPTIONS) {
      for (const s of opt.strings) {
        if (s === shortPrefix) {
          result.push({ opt, optionString: s, explicitArg: shortExplicit, viaSep: false });
        } else if (s.startsWith(prefix)) {
          const explicitArg2 = eq === -1 ? null : arg.slice(eq + 1);
          result.push({ opt, optionString: s, explicitArg: explicitArg2, viaSep: eq !== -1 });
        }
      }
    }
  }
  return result;
}

// Mirror of argparse._parse_optional.
// Returns null when arg is value-like; otherwise a match object
// ({ opt: null } for an unknown option-like string).
function parseOptional(arg) {
  // not an option string at all
  if (arg.length === 0 || arg[0] !== '-') return null;
  // exact match
  if (OPTION_MAP.has(arg)) {
    return { opt: OPTION_MAP.get(arg), optionString: arg, explicitArg: null, viaSep: false };
  }
  // a single '-' is a value
  if (arg.length === 1) return null;
  // --opt=value with an exact option head
  const eq = arg.indexOf('=');
  if (eq !== -1) {
    const head = arg.slice(0, eq);
    if (OPTION_MAP.has(head)) {
      return { opt: OPTION_MAP.get(head), optionString: head, explicitArg: arg.slice(eq + 1), viaSep: true };
    }
  }
  // prefix matching
  const tuples = getOptionTuples(arg);
  if (tuples.length > 1) {
    const names = tuples.map((t) => t.optionString).join(', ');
    errorAndExit('ambiguous option: ' + arg + ' could match ' + names);
  } else if (tuples.length === 1) {
    return tuples[0];
  }
  // negative numbers are values (this parser has no number-like options)
  if (looksLikeNegativeNumber(arg)) return null;
  // strings containing spaces are values
  if (arg.indexOf(' ') !== -1) return null;
  // unknown option-like string
  return { opt: null, optionString: arg, explicitArg: null, viaSep: false };
}

export function parseArgs(argv) {
  const values = { a: undefined, b: undefined };
  const extras = [];
  let afterDoubleDash = false;

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (afterDoubleDash) {
      extras.push(arg);
      continue;
    }
    if (arg === '--') {
      // No positionals are defined, so the '--' itself lands in extras.
      afterDoubleDash = true;
      extras.push(arg);
      continue;
    }
    const match = parseOptional(arg);
    if (match === null) {
      // value-like string with no positional to consume it
      extras.push(arg);
      continue;
    }
    const { opt, explicitArg, viaSep } = match;
    if (opt === null) {
      extras.push(arg);
      continue;
    }
    if (opt.dest === 'help') {
      if (explicitArg !== null && (viaSep || explicitArg.length === 0 || explicitArg[0] === '-')) {
        errorAndExit(
          'argument -h/--help: ignored explicit argument ' + "'" + explicitArg + "'"
        );
      }
      // -h<cluster> runs the help action before any further cluster parsing.
      printHelpAndExit();
    }
    // --a / --b: require exactly one argument
    let value;
    if (explicitArg !== null) {
      value = explicitArg;
    } else {
      const next = i + 1 < argv.length ? argv[i + 1] : undefined;
      if (next !== undefined && next !== '--' && parseOptional(next) === null) {
        value = next;
        i++;
      } else {
        errorAndExit('argument ' + opt.strings.join('/') + ': expected one argument');
      }
    }
    values[opt.dest] = value;
  }

  const missing = [];
  if (values.a === undefined) missing.push('--a');
  if (values.b === undefined) missing.push('--b');
  if (missing.length > 0) {
    errorAndExit('the following arguments are required: ' + missing.join(', '));
  }
  if (extras.length > 0) {
    errorAndExit('unrecognized arguments: ' + extras.join(' '));
  }
  return { a: values.a, b: values.b };
}

