cat > /tmp/pyz/extract2.mjs <<'EOF'
import { readFileSync, writeFileSync } from 'node:fs';
import zlib from 'node:zlib';
const buf = readFileSync('/workspace/dataset/test6_executable');
const want = {
  'htmlparser': ['HTMLExtractor', 'block_level_tags'],
  'preprocessors': ['NormalizeWhitespace', 'HtmlBlockPreprocessor'],
  'postprocessors': ['RawHtmlPostprocessor', 'AndSubstitutePostprocessor'],
  'treeprocessors': ['InlineProcessor', 'PrettifyTreeprocessor'],
  'serializers': ['_escape_attrib_html', 'to_html_string'],
  'util': ['HTML_PLACEHOLDER', 'AtomicString'],
  'blockparser': ['parseChunk', 'parseDocument'],
  'core': ['class Markdown', 'output_formats'],
  'inlinepatterns': ['InlineProcessor', 'BacktickInlineProcessor'],
};
const found = {};
let i = 19000000;
while ((i = buf.indexOf(0x78, i)) !== -1 && i < buf.length) {
  if (buf[i+1] === 0x9c) {
    try {
      const out = zlib.inflateSync(buf.subarray(i), { maxOutputLength: 50*1024*1024 });
      const s = out.toString('latin1');
      for (const [name, needles] of Object.entries(want)) {
        if (!found[name] && needles.every(n => s.includes(n)) && s.includes('markdown/')) {
          found[name] = out;
          writeFileSync('/tmp/pyz/mod_' + name + '.bin', out);
          console.log('found', name, 'at', i, 'len', out.length);
        }
      }
    } catch (e) {}
  }
  i++;
}
console.log('missing:', Object.keys(want).filter(k => !found[k]));
EOF
node /tmp/pyz/extract2.mjs

